using System.ComponentModel;
using Microsoft.Extensions.AI;
using Microsoft.Extensions.Configuration;
using Microsoft.Extensions.DependencyInjection;
using Microsoft.Extensions.Logging;
using Microsoft.Agents.AI;
using ResearchAgent;

var configuration = new ConfigurationBuilder()
    .AddEnvironmentVariables()
    .Build();

var apiKey = configuration["OPENAI_API_KEY"]
    ?? throw new InvalidOperationException(
        "Set the OPENAI_API_KEY environment variable to run this agent.");

var modelId = configuration["OPENAI_MODEL"] ?? "gpt-4o-mini-2024-07-18";

var services = new ServiceCollection();

services.AddLogging(builder => builder
    .AddConsole()
    .SetMinimumLevel(LogLevel.Information));

services.AddChatClient(builder => builder
    .UseOpenAIChatClient(modelId, new OpenAI.OpenAIClient(apiKey)));

var provider = services.BuildServiceProvider();
var chatClient = provider.GetRequiredService<IChatClient>();
var logger = provider.GetRequiredService<ILogger<Program>>();

// Create research tools
var notepad = new Notepad();
var tools = new AIToolCollection
{
    AIFunctionFactory.Create(WebSearchTool.SearchWebAsync),
    AIFunctionFactory.Create(notepad.AddNote),
    AIFunctionFactory.Create(notepad.GetNotes),
};

// Configure the agent
var agent = new ChatClientAgent(chatClient, "ResearchAgent")
{
    Instructions = """
        You are a research agent. Given a topic, you search the web to gather relevant
        information, take notes on key findings, and then produce a concise summary.

        Your workflow:
        1. Break the topic into 2-3 search queries
        2. Search the web for each query
        3. Take notes on important findings from each search
        4. After gathering enough information, review your notes and provide a final summary

        Always take notes before summarizing. Be thorough but concise.
        """,
    Tools = tools,
};

// Get the research topic
Console.Write("Enter a research topic: ");
var topic = Console.ReadLine()?.Trim();
if (string.IsNullOrEmpty(topic))
{
    Console.WriteLine("No topic provided. Exiting.");
    return;
}

logger.LogInformation("Researching topic: {Topic}", topic);

var history = new List<ChatMessage>
{
    new(ChatRole.User, $"Research the following topic and provide a summary: {topic}"),
};

var options = new AgentInvokeOptions
{
    MaximumIterations = 10,
};

// Run the agent loop
Console.WriteLine($"\n🔍 Researching: {topic}\n");

await foreach (var message in agent.InvokeStreamingAsync(history, options))
{
    if (message.Role == ChatRole.Assistant && !string.IsNullOrEmpty(message.Text))
    {
        Console.Write(message.Text);
    }
}

Console.WriteLine("\n\n📝 Notes collected during research:");
foreach (var note in notepad.GetAllNotes())
{
    Console.WriteLine($"  • {note}");
}

