using System.ComponentModel;
using System.Net.Http.Json;
using System.Text.Json;

namespace ResearchAgent;

public static class WebSearchTool
{
    private static readonly HttpClient HttpClient = new();

    [Description("Searches the web for information on a given query and returns relevant results.")]
    public static async Task<string> SearchWebAsync(
        [Description("The search query to look up")] string query,
        CancellationToken cancellationToken = default)
    {
        // Use a public search API (DuckDuckGo Instant Answer API)
        var encodedQuery = Uri.EscapeDataString(query);
        var url = $"https://api.duckduckgo.com/?q={encodedQuery}&format=json&no_html=1&skip_disambig=1";

        try
        {
            var response = await HttpClient.GetStringAsync(url, cancellationToken);
            var doc = JsonDocument.Parse(response);
            var root = doc.RootElement;

            var results = new List<string>();

            // Extract abstract
            var abstractText = root.GetProperty("AbstractText").GetString();
            if (!string.IsNullOrWhiteSpace(abstractText))
            {
                var source = root.GetProperty("AbstractSource").GetString();
                results.Add($"[{source}] {abstractText}");
            }

            // Extract related topics
            if (root.TryGetProperty("RelatedTopics", out var relatedTopics))
            {
                foreach (var topic in relatedTopics.EnumerateArray().Take(5))
                {
                    if (topic.TryGetProperty("Text", out var text))
                    {
                        var topicText = text.GetString();
                        if (!string.IsNullOrWhiteSpace(topicText))
                        {
                            results.Add(topicText);
                        }
                    }
                }
            }

            if (results.Count == 0)
            {
                return $"No detailed results found for '{query}'. Try a more specific query.";
            }

            return string.Join("\n\n", results);
        }
        catch (HttpRequestException ex)
        {
            return $"Search failed for '{query}': {ex.Message}";
        }
    }
}

using System.ComponentModel;

namespace ResearchAgent;

public sealed class Notepad
{
    private readonly List<string> _notes = [];

    [Description("Adds a note capturing a key finding from research. Use this to record important facts.")]
    public string AddNote(
        [Description("The note text to save")] string note)
    {
        _notes.Add(note);
        return $"Note saved ({_notes.Count} total notes).";
    }

    [Description("Retrieves all notes taken so far during the research session.")]
    public string GetNotes()
    {
        if (_notes.Count == 0)
        {
            return "No notes taken yet.";
        }

        return string.Join("\n", _notes.Select((n, i) => $"{i + 1}. {n}"));
    }

    public IReadOnlyList<string> GetAllNotes() => _notes.AsReadOnly();
}

